"""PreToolUse(Write|Edit|MultiEdit|NotebookEdit): block direct edits to protected files."""

from pathlib import PurePath

from _hook_io import deny_tool, read_payload, tool_input_str

# Compared case-insensitively against the file name only.
PROTECTED = {
    "uv.lock": "uv.lock is generated by uv. Change dependencies with `uv add` / `uv remove` / `uv lock`.",
    "license": "LICENSE must not be edited by Claude. Ask the user to change it themselves.",
    "license.md": "LICENSE must not be edited by Claude. Ask the user to change it themselves.",
    "license.txt": "LICENSE must not be edited by Claude. Ask the user to change it themselves.",
}


def main() -> None:
    payload = read_payload()
    path = tool_input_str(payload, "file_path", "notebook_path")
    if path is None:
        return
    # Normalise backslashes so Windows paths split correctly on every OS.
    name = PurePath(path.replace("\\", "/")).name.lower()
    reason = PROTECTED.get(name)
    if reason:
        deny_tool(f"Direct edits to {name} are blocked. {reason}")


if __name__ == "__main__":
    main()
